cy.get(`.entry-title`).should("contain.text", "Page Not Found");
cy.get(`.intro-text`).should("contain.text", "The page you were looking for could not be found. It might have been removed, renamed, or did not exist in the first place.");
cy.get(`.screen-reader-text`).should("contain.text", "Search for:");
cy.get(`#s`).should("be.visible"); //input search field
cy.get(`#searchsubmit`).should("be.visible"); //search button

cy.iframe().contains(`.hs-submit input[class*="hs-button"]`, "Submit").scrollIntoView().click();
cy.iframe().find(".hs_error_rollup label").scrollIntoView().should("contain.text", "Please complete all required fields.");
cy.fixture("bookDemoFieldNames.json").then(fields => {
  for (const field_name of fields) cy.iframe().contains("form label", field_name).parents('div[class*="field"]').find(".hs-error-msgs").scrollIntoView().should("contain.text", "Please complete this required field.");
});

cy.Ifield(`firstname`).type(_faker.faker.person.firstName());
cy.Ifield(`lastname`).type(_faker.faker.person.lastName());
cy.Ifield(`email`).type(_faker.faker.internet.email());
cy.Ifield(`phone`).type(_faker.faker.phone.number());
cy.Ifield(`organization_name`).type(_faker.faker.company.name());
cy.Ifield(`provider_range`).select("0-14");
cy.Ifield(`organization_type`).select("Other");
cy.Ifield(`ehr`).select("Other");
cy.Ifield(`other_ehr`).type(_faker.faker.lorem.words());
cy.Ifield(`what_are_you_interested_in_`).type(_faker.faker.lorem.paragraph());
cy.Ifield(`how_d_you_hear_about_us_`).type(_faker.faker.lorem.paragraph());
cy.iframe().contains(`.hs-submit input[class*="hs-button"]`, "Submit").scrollIntoView().click();
cy.iframe().find(".hs_error_rollup label").scrollIntoView().should("contain.text", "Failed to validate Captcha. Please try again.");

cy.get(`.hero-section-title`).should("be.visible").and("contain.text", "Manual Tasks’ Worst Nightmare");
cy.get(`.hero-section-subtitle`).should("be.visible").invoke("text").then(text => {
  const cleanedText = text.replace(/\s+/g, " ").trim();
  expect(cleanedText).to.contain("Luma's AI-native Patient Success Platform™ makes it easier for patients who need care to get to you, and eliminates manual work for your staff.");
});

cy.contains(`.hero-button`, "See what it does").should("be.visible").click();
cy.url().should("include", "/patient-success-platform/");
cy.iframe().contains("The Patient Success Platform").should("be.visible");

cy.get(`.hero-section-title`).should("be.visible").and("contain.text", "Manual Tasks’ Worst Nightmare");
cy.get(`.hero-section-subtitle`).should("be.visible").invoke("text").then(text => {
  const cleanedText = text.replace(/\s+/g, " ").trim();
  expect(cleanedText).to.contain("Luma's AI-native Patient Success Platform™ makes it easier for patients who need care to get to you, and eliminates manual work for your staff.");
});

cy.get(".navbar-trigger").should("be.visible").click();
cy.fixture("navegationBar.json").then(obj => {
  for (const {
    nav
  } of obj) {
    cy.contains(".mobile-accordion", nav).should("be.visible").click().should("have.class", "active");
    cy.contains(".hide-desktop", nav).click();
    cy.contains(".mobile-accordion", nav).should("not.have.class", "active");
  }
});

